import yaml,glob,os
bad=[]
for f in sorted(glob.glob('*.yaml')):
    try:
        d=yaml.safe_load(open(f))
    except Exception as e:
        bad.append((f,'PARSE',str(e)[:60])); continue
    if d is None: bad.append((f,'EMPTY',os.path.getsize(f)))
    elif not isinstance(d,dict): bad.append((f,'NOTDICT',type(d).__name__))
    elif 'scope' in d and d['scope'] is not None and not isinstance(d['scope'],dict): bad.append((f,'SCOPE',repr(d['scope'])[:40]))
print('total files',len(glob.glob('*.yaml')))
for b in bad: print(b)
"
